<div class="crpcrm-request-filters"><form method="get"><input type="hidden" name="page" value="crpcrm-staff"><input type="hidden" name="staff_tab" value="tasks"><div class="crpcrm-filter-grid"><?php if($can_manage): ?><label>مسئول<select name="assigned_to"><option value="">همه</option><?php foreach($staff_users as $u): ?><option value="<?php echo esc_attr($u->ID); ?>" <?php selected($filters['assigned_to'] ?? '',$u->ID); ?>><?php echo esc_html($u->display_name); ?></option><?php endforeach; ?></select></label><?php endif; ?><label>وضعیت<select name="status"><option value="">همه</option><?php foreach($task_statuses as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['status'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>اولویت<select name="priority"><option value="">همه</option><?php foreach($priorities as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['priority'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>عقب‌افتاده<select name="overdue"><option value="">همه</option><option value="1" <?php selected($filters['overdue'] ?? '','1'); ?>>فقط عقب‌افتاده</option></select></label></div><?php submit_button('اعمال فیلتر','secondary','',false); ?></form></div>
